from backend.features.local_browser_storage.feature import blueprint as local_browser_storage_blueprint
from backend.features.record_item_and_borrower.feature import blueprint as record_item_and_borrower_blueprint
from backend.features.view_loan_list.feature import blueprint as view_loan_list_blueprint



def create_app(testing: bool = False, config=None) -> Flask:
    settings = None if testing else get_settings()
    app = Flask(__name__, template_folder=str(Path(__file__).resolve().parents[1] / 'frontend'), static_folder=None)
    app.config.update(
        TESTING=bool(testing),
        DATABASE_URL='sqlite+pysqlite:///:memory:' if testing else settings.database_url,
        SECRET_KEY='test-only-secret-at-least-32-characters' if testing else settings.jwt_secret,
        JWT_SECRET='test-only-secret-at-least-32-characters' if testing else settings.jwt_secret,
        JWT_ISSUER='zorentia-app' if testing else settings.jwt_issuer,
        SESSION_COOKIE_NAME='lendlog_session', SESSION_COOKIE_HTTPONLY=True,
        SESSION_COOKIE_SECURE=os.getenv('COOKIE_SECURE', 'false').lower() == 'true',
        SESSION_COOKIE_SAMESITE='Lax',
        MAX_CONTENT_LENGTH=16 * 1024,
    )
    if config:
        app.config.update(config)
    configure_database(app)
    register_error_handlers(app)
    install_auth(app)
    app.register_blueprint(authentication_blueprint)
    app.register_blueprint(local_browser_storage_blueprint)
    app.register_blueprint(record_item_and_borrower_blueprint)
    app.register_blueprint(view_loan_list_blueprint)
    # This backend has no background feature registrations.

    @app.get("/health")
    def health():
        engine = app.extensions.get('database_engine')
        if engine is not None:
            try:
                with engine.connect() as connection:
                    connection.execute(text('SELECT 1'))
            except Exception:
                app.logger.exception('Database health check failed')
                return jsonify(ok=False, service='lendlog-backend', database='unavailable'), 503
        return jsonify(ok=engine is not None, service='lendlog-backend', database='ok' if engine else 'not-configured'), 200 if engine else 503

    @app.after_request
    def security_headers(response):
        response.headers['Content-Security-Policy'] = "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; form-action 'self'; frame-ancestors 'none'; base-uri 'self'"
        response.headers['X-Content-Type-Options'] = 'nosniff'
        response.headers['X-Frame-Options'] = 'DENY'
        response.headers['Referrer-Policy'] = 'same-origin'
        if response.mimetype in {'text/html', 'application/json'}:
            response.headers['Cache-Control'] = 'no-store'
        return response

    return app
